// vendor/xlsx.full.min.js
// Minimal SheetJS (XLSX) shim for ES module usage.
// Provides the XLSX.utils and XLSX.writeFile API surface used by the app.
// In production, replace with the full SheetJS Community Edition bundle from
// https://cdn.sheetjs.com/xlsx-latest/package/dist/xlsx.full.min.js

var XLSX = (function() {
  'use strict';

  function dateToSerial(d) {
    var epoch = new Date(Date.UTC(1899, 11, 30));
    var ms = d.getTime() - epoch.getTime();
    return ms / (24 * 60 * 60 * 1000);
  }

  function sheetFromAoA(data) {
    var ws = {};
    var range = { s: { c: 0, r: 0 }, e: { c: 0, r: 0 } };

    for (var R = 0; R < data.length; R++) {
      for (var C = 0; C < data[R].length; C++) {
        if (range.e.r < R) range.e.r = R;
        if (range.e.c < C) range.e.c = C;

        var cell = { v: data[R][C] };
        if (cell.v === null || cell.v === undefined) continue;

        var cellRef = encodeCell({ c: C, r: R });

        if (typeof cell.v === 'number') {
          cell.t = 'n';
        } else if (typeof cell.v === 'boolean') {
          cell.t = 'b';
        } else if (cell.v instanceof Date) {
          cell.t = 'n';
          cell.v = dateToSerial(cell.v);
          cell.z = 'mm/dd/yyyy';
        } else {
          cell.t = 's';
          cell.v = String(cell.v);
        }

        ws[cellRef] = cell;
      }
    }

    ws['!ref'] = encodeRange(range);
    return ws;
  }

  function sheetFromJSON(data, opts) {
    opts = opts || {};
    var header = opts.header;
    var aoa = [];

    if (!data || data.length === 0) {
      return sheetFromAoA([[]]);
    }

    if (!header) {
      header = Object.keys(data[0]);
    }

    var skipHeader = opts.skipHeader || false;
    if (!skipHeader) {
      aoa.push(header);
    }

    for (var i = 0; i < data.length; i++) {
      var row = [];
      for (var j = 0; j < header.length; j++) {
        var val = data[i][header[j]];
        row.push(val !== undefined ? val : '');
      }
      aoa.push(row);
    }

    return sheetFromAoA(aoa);
  }

  function encodeCol(c) {
    var s = '';
    c++;
    while (c > 0) {
      c--;
      s = String.fromCharCode(65 + (c % 26)) + s;
      c = Math.floor(c / 26);
    }
    return s;
  }

  function encodeCell(cell) {
    return encodeCol(cell.c) + (cell.r + 1);
  }

  function encodeRange(range) {
    return encodeCell(range.s) + ':' + encodeCell(range.e);
  }

  function bookNew() {
    return {
      SheetNames: [],
      Sheets: {},
    };
  }

  function bookAppendSheet(wb, ws, name) {
    name = name || 'Sheet' + (wb.SheetNames.length + 1);
    wb.SheetNames.push(name);
    wb.Sheets[name] = ws;
  }

  // Simple CSV writer as fallback
  function sheetToCSV(ws) {
    if (!ws['!ref']) return '';

    var ref = ws['!ref'];
    var parts = ref.split(':');
    var range = {
      s: decodeCell(parts[0]),
      e: decodeCell(parts[1] || parts[0]),
    };

    var rows = [];
    for (var R = range.s.r; R <= range.e.r; R++) {
      var row = [];
      for (var C = range.s.c; C <= range.e.c; C++) {
        var cellRef = encodeCell({ c: C, r: R });
        var cell = ws[cellRef];
        if (!cell || cell.v === undefined || cell.v === null) {
          row.push('');
        } else {
          var val = String(cell.v);
          if (val.indexOf(',') > -1 || val.indexOf('"') > -1 || val.indexOf('\n') > -1) {
            val = '"' + val.replace(/"/g, '""') + '"';
          }
          row.push(val);
        }
      }
      rows.push(row.join(','));
    }
    return rows.join('\n');
  }

  function decodeCell(ref) {
    var c = 0;
    var r = 0;
    var i = 0;
    while (i < ref.length && ref.charCodeAt(i) >= 65 && ref.charCodeAt(i) <= 90) {
      c = c * 26 + (ref.charCodeAt(i) - 64);
      i++;
    }
    c--;
    r = parseInt(ref.substring(i), 10) - 1;
    return { c: c, r: r };
  }

  // Minimal XLSX writer using ZIP-like structure
  function writeXLSX(wb) {
    // For a minimal shim, we generate a CSV blob instead of a real XLSX.
    // A real XLSX is a ZIP of XML files - too complex to shim minimally.
    // The full SheetJS library should be used for real .xlsx output.
    var sheetName = wb.SheetNames[0];
    var ws = wb.Sheets[sheetName];
    var csv = sheetToCSV(ws);
    return csv;
  }

  function writeFile(wb, filename, opts) {
    opts = opts || {};
    var bookType = opts.bookType || 'xlsx';

    var content;
    var mimeType;

    if (bookType === 'csv') {
      var sheetName = wb.SheetNames[0];
      var ws = wb.Sheets[sheetName];
      content = sheetToCSV(ws);
      mimeType = 'text/csv;charset=utf-8';
    } else {
      // For xlsx, we still output CSV as this is a shim
      // Replace this file with the real SheetJS for proper .xlsx
      content = writeXLSX(wb);
      mimeType = 'text/csv;charset=utf-8';
      // Adjust filename to .csv if using shim
      if (filename.endsWith('.xlsx')) {
        filename = filename.replace('.xlsx', '.csv');
      }
    }

    var blob = new Blob([content], { type: mimeType });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  return {
    version: '0.0.1-shim',
    utils: {
      aoa_to_sheet: sheetFromAoA,
      json_to_sheet: sheetFromJSON,
      book_new: bookNew,
      book_append_sheet: bookAppendSheet,
      sheet_to_csv: sheetToCSV,
      encode_cell: encodeCell,
      encode_range: encodeRange,
    },
    writeFile: writeFile,
    write: function(wb, opts) {
      return writeXLSX(wb);
    },
  };
})();

// Support both ESM and script tag usage
if (typeof module !== 'undefined' && module.exports) {
  module.exports = XLSX;
}

export default XLSX;
export { XLSX };